# Login to phone app and then fetch all alarms (paginated)
import re

phone_password = None
for a in apis.supervisor.show_account_passwords():
    if a['account_name']=='phone':
        phone_password = a['password']
        break

phone_number = '4436271690'

login_resp = apis.phone.login(username=phone_number, password=phone_password)
print('login_resp', login_resp)
access_token = login_resp['access_token']

alarms = []
page_index = 0
while True:
    page = apis.phone.show_alarms(access_token=access_token, page_index=page_index, page_limit=20)
    # Expect page to be dict/list. Let's print keys/type.
    print('page_index', page_index, 'page_type', type(page))
    if page is None:
        break
    # If API returns {'success': [...]} or similar, handle
    if isinstance(page, dict):
        if 'alarms' in page:
            page_alarms = page['alarms']
        elif 'success' in page and isinstance(page['success'], list):
            page_alarms = page['success']
        elif 'data' in page and isinstance(page['data'], list):
            page_alarms = page['data']
        else:
            # maybe page itself is list under unknown key
            page_alarms = page.get('result') or page.get('items')
    else:
        page_alarms = page
    if not page_alarms:
        break
    alarms.extend(page_alarms)
    page_index += 1
    if page_index>50:
        break

print('total_alarms', len(alarms))
# Print brief info for verification
for al in alarms:
    print({'alarm_id': al.get('alarm_id'), 'time': al.get('time'), 'label': al.get('label'), 'enabled': al.get('enabled'), 'created_at': al.get('created_at'), 'repeat_days': al.get('repeat_days')})

